    "feio":    ["horrendo", "horroroso", "disforme", "monstruoso", "repulsivo", "repelente"],

    // Nascentes: "Grande, Imane, Ingente, Magno — Grande é o mais genérico"
    "grande":    ["imenso", "vasto", "gigantesco", "amplo", "colossal", "majestoso"],

    // est
